            parts = listOf(
                StoryPart(1, "A Box Above the Harbour", listOf("During a library clean-up, Tobi found a tin of postcards behind an atlas. Each showed the same lighthouse in a different year.", "The cards had never been mailed. Their dates stretched across four decades, and each carried a message addressed to 'Whoever keeps the light'.", "The librarian suggested they might belong in the local history collection.")),
                StoryPart(2, "The Keeper's Initials", listOf("The earliest card was signed E.A. and described a storm that damaged the harbour steps.", "The town archive listed several lighthouse keepers with those initials, but did not identify the writer.", "Tobi noticed a drawing of three waves in the corner of every card.")),
                StoryPart(3, "A Repeated Symbol", listOf("A retired harbour worker recognised the waves as a mark used by the lighthouse volunteers' association.", "Members exchanged notes during annual maintenance visits, recording repairs, weather, and visitors.", "He suggested contacting a former member who volunteered at the maritime museum.")),
                StoryPart(4, "The Museum Ledger", listOf("A museum volunteer found a ledger listing lighthouse visits and maintenance teams. Several dates matched the postcards.", "The cards recorded details missing from the ledger: a school visit, a misplaced toolbox, and the restoration of the old lantern.", "One card mentioned a final entry kept inside the lighthouse.")),
                StoryPart(5, "Permission First", listOf("Tobi wanted to search the lighthouse, but the volunteer explained that the protected building could only be entered by authorised staff.", "They contacted the heritage office and shared photographs of the cards. An officer agreed to inspect the site during scheduled maintenance.", "The students prepared questions and promised not to handle objects without permission.")),
                StoryPart(6, "The Final Entry", listOf("During the authorised visit, the officer found a weatherproof envelope in a cabinet.", "It explained that volunteers had planned a public history record, but lost their meeting place before finishing. The postcards were meant to guide future residents.", "The final message asked readers to include harbour workers, not only lighthouse keepers.")),
                StoryPart(7, "Voices from the Harbour", listOf("Tobi and the librarian invited former workers to share memories. They recorded interviews with permission and checked dates against the ledger.", "A mechanic described maintaining the steps; a teacher remembered coastal-weather lessons; a volunteer spoke about restoring the lantern.", "Each contributor reviewed their own words before publication.")),
                StoryPart(8, "A Public Exhibition", listOf("The museum prepared an exhibition with postcard images, ledger extracts, and short audio recordings.", "The heritage officer checked the display for accuracy and ensured it did not reveal sensitive site details.", "Visitors followed the lighthouse's history and heard how many people had cared for it.")),
                StoryPart(9, "The New Postcard", listOf("At the opening, former volunteers met again and were pleased that everyday work had been preserved alongside major restoration events.", "The librarian placed a blank postcard beside the tin. Visitors could write what they hoped future generations would remember.", "Tobi wrote that a town's history belongs to everyone who helps keep it going.")),
                StoryPart(10, "Whoever Keeps the Light", listOf("The exhibition remained at the museum, and the library kept a digital copy of the cards and approved interviews.", "The tin was returned to a secure archive case, and the heritage office scheduled another community history day.", "Tobi added a postcard thanking the keepers, workers, teachers, and volunteers. The town had become the future reader the original writers hoped would answer."))
